Treat 401 AND 403 as 'not authenticated' (user.value = null). Also clear user on any error coming from /api/auth/me to avoid stale state:

async function fetchUser() {
  try {
    userState.value = await useApi()<User>('/api/auth/me')
  } catch (e: unknown) {
    const code = (e as any)?.statusCode ?? (e as any)?.status ?? (e as any)?.response?.status
    if (code === 401 || code === 403) {
      userState.value = null
      return
    }
    userState.value = null  // fail-closed
    throw e
  }
}

