Distinguish 'session already gone' (acceptable to clear) from 'request failed' (surface to user, do NOT clear local state and show a retry):

async function logout() {
  try {
    await useApi()('/api/auth/logout', { method: 'POST' })
    userState.value = null
  } catch (e: any) {
    const code = e?.statusCode ?? e?.status
    if (code === 401) { userState.value = null; return }
    // 403 / network error — report to user, keep state as-is
    throw e
  }
}

